import { useState } from 'react';
import { View, TextInput, Text } from 'react-native';

type FormAlamat = {
  penerima: string;
  telepon: string;
  alamat: string;
  catatan: string;
};

export function FormPengiriman({ onSimpan }: { onSimpan: (data: FormAlamat) => void }) {
  const [form, setForm] = useState<FormAlamat>({
    penerima: '',
    telepon: '',
    alamat: '',
    catatan: '',
  });

  // satu fungsi update untuk semua field, tetap aman
  const ubah = <K extends keyof FormAlamat>(field: K, nilai: FormAlamat[K]) => {
    setForm((sebelumnya) => ({ ...sebelumnya, [field]: nilai }));
  };

  return (
    <View style={{ gap: 12 }}>
      <TextInput
        placeholder="Nama penerima"
        value={form.penerima}
        onChangeText={(teks) => ubah('penerima', teks)}
      />
      <TextInput
        placeholder="Nomor HP"
        keyboardType="phone-pad"
        value={form.telepon}
        onChangeText={(teks) => ubah('telepon', teks)}
      />
      <TextInput
        placeholder="Alamat lengkap"
        multiline
        value={form.alamat}
        onChangeText={(teks) => ubah('alamat', teks)}
      />
    </View>
  );
}

// ubah('telpon', teks)  ❌ Argument of type '"telpon"' is not assignable
//                          to parameter of type keyof FormAlamat

type ErrorForm = Partial<Record<keyof FormAlamat, string>>;
// hasilnya: { penerima?: string; telepon?: string; alamat?: string; catatan?: string }

function validasi(form: FormAlamat): ErrorForm {
  const error: ErrorForm = {};
  if (!form.penerima.trim()) error.penerima = 'Nama penerima wajib diisi';
  if (!/^08\d{8,11}$/.test(form.telepon)) error.telepon = 'Nomor HP tidak valid';
  if (form.alamat.trim().length < 10) error.alamat = 'Alamat terlalu pendek';
  return error;
}

